    //alert("inputCalendar14 EnableAllDate");		
};
scwin.__isBeforeDisabled = function() {
    var count = 0;
    var el = WebSquare.wUnit.getJq("#inputCalendar13_calendar_cell_2_2").prevAll();
    var length = el.length;
    el.each(function() {
        if (WebSquare.wUnit.getJq(this).hasClass("w2calendar_date_disable")) {
            count++;
        }
    });
    WebSquare.wUnit.getJq("#inputCalendar13_calendar_cell_2_2").parent().prevAll().each(function() {
        WebSquare.wUnit.getJq(this).find("td").each(function() {
            if (WebSquare.wUnit.getJq(this).hasClass("w2calendar_date_disable")) {
                count++;
            }
            length++;
        });
    });
    return length == count;
}
scwin.__isAfterDisabled = function() {
    var count = 0;
    var el = WebSquare.wUnit.getJq("#inputCalendar14_calendar_cell_2_2").nextAll();
    var length = el.length;
    el.each(function() {
        if (WebSquare.wUnit.getJq(this).hasClass("w2calendar_date_disable")) {
            count++;
        }
    });
    WebSquare.wUnit.getJq("#inputCalendar14_calendar_cell_2_2").parent().nextAll().each(function() {
        WebSquare.wUnit.getJq(this).find("td").each(function() {
            if (WebSquare.wUnit.getJq(this).hasClass("w2calendar_date_disable")) {
                count++;
            }
            length++;
        });
    });
    return length == count;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 5. 브라우저에서 inputCalendar13 의 달력아이콘을 클릭후 임의의 날짜를 선택후 (예 : 2017-04-17) 다시 달력아이콘을 클릭해서 확인한다. 
    //5. In your browser, click the calendar icon for inputCalendar13, select an arbitrary date (eg 2017-04-17), and click on the calendar icon again.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar13_img').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar13_calendar_cell_2_2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar13_input').blur()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar13_img').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 5. 2017-04-17 이전날짜들이 Disable 처리된다.
    //5. The dates before 2017-04-17 are disabled.
    WebSquare.wUnit.addCommand("assert", "scwin.__isBeforeDisabled()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 6. inputCalendar13.enableAllDate() 버튼을 클릭한다.
    //6. Click the inputCalendar13.enableAllDate () button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 6. 'inputCalendar13 EnableAllDate' 팝업이 생성되면서 동적으로 disable 처리된 날짜가 다시 enable 처리된다. 
    //6. When the 'inputCalendar13 EnableAllDate' popup is generated, the dynamically disable date is re-enabled.
    WebSquare.wUnit.addCommand("assert", "showAlertCal13", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__isBeforeDisabled()", "false");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 7. inputCalendar14 의 달력아이콘을 클릭후 임의의 날짜를 선택후 (예 : 2017-04-17) 다시 달력아이콘을 클릭해서 확인한다. 
    //7. Click on the calendar icon in inputCalendar14, select an arbitrary date (eg 2017-04-17) and click on the calendar icon again.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar14_img').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar14_calendar_cell_2_2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar14_input').blur()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar14_img').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 7. 2017-04-17 이후날짜들이 Disable 처리된다.
    //7. The dates after 2017-04-17 are disabled.
    WebSquare.wUnit.addCommand("assert", "scwin.__isAfterDisabled()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 8. inputCalendar14.enableAllDate() 버튼을 클릭한다.기타. 임의로 5 ~ 8번 절차를 반복한다.
    //8. Click the inputCalendar14.enableAllDate () button.Etc. Repeat steps 5 to 8 as required.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 8. 'inputCalendar14 EnableAllDate' 팝업이 생성되면서 동적으로 disable 처리된 날짜가 다시 enable 처리된다.
    //8. When the 'inputCalendar14 EnableAllDate' popup is generated, the dynamically disable date is re-enabled.
    WebSquare.wUnit.addCommand("assert", "showAlertCal13", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__isBeforeDisabled()", "false");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.showAlertCal13 = false;
    window.showAlertCal14 = false;
    //Function unitTest
    //Created By: Sang.do
    //Created By: 12-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
